using Microsoft.AspNetCore.SignalR;
using System.Threading.Tasks;
namespace Demo.Realtime.Hubs
{
    public class OrdersHub : Hub
    {
        public async Task PublishOrderStatus(int projectId, int orderId, string status)
        {
            await Clients.All.SendAsync("OrderStatusChanged", orderId, status);
        }
        public override async Task OnConnectedAsync()
        {
            var apiKey = Context.GetHttpContext()?.Request.Query["apiKey"].ToString();
            if (string.IsNullOrEmpty(apiKey))
            {
                Context.Abort();
                return;
            }
            await base.OnConnectedAsync();
        }
    }
}

