        {
            var apiKey = Context.GetHttpContext()?.Request.Query["apiKey"].ToString();
            if (string.IsNullOrEmpty(apiKey))
            {
                Context.Abort();
                return;
            }
            await base.OnConnectedAsync();
        }
    }
}

